"use client";
import { useState } from "react";
import Image from "next/image";
import HadiTechLogo from "./../../public/haditechlogo.svg";
import TagLogo from "./../../public/Name_Tag_Combined.svg";

export default function MainPage() {
  // Track which section is selected
  const [active, setActive] = useState("home");

  // Function to scroll to a section by ID
  const scrollToSection = (id) => {
    const section = document.getElementById(id);
    if (section) {
      section.scrollIntoView({ behavior: "smooth" });
    }
    setActive(id); // Mark the clicked button as active
  };

  const navItems = [
    { id: "home", label: "Home" },
    { id: "work", label: "Work" },
    { id: "services", label: "Services" },
    { id: "price", label: "Price" },
  ];

  return (
    <header className="bg-gray-100 sticky top-0 z-50 border-b border-gray-200 opacity-90 rounded-t-xl">
      <nav
        className="flex items-center justify-between px-6 py-4"
        aria-label="Global"
      >
        {/* Left Logos */}
        <div className="flex items-start">
          <Image
            className="h-12 w-auto"
            priority
            src={HadiTechLogo}
            alt="Logo of Haadi Tech"
          />
          <Image
            className="h-12 w-auto ml-4 pt-1"
            priority
            src={TagLogo}
            alt="Tagline Logo"
          />
        </div>

        {/* Desktop Navigation */}
        <div className="hidden md:flex space-x-8 text-gray-700 font-medium">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => scrollToSection(item.id)}
              className={`font-bold text-xl ${
                active === item.id
                  ? "border-b-2 border-[#004a8f] text-[#004a8f]"
                  : "text-[#004a8f] hover:text-[#003366]"
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>

        {/* Contact Us Button (Optional) */}
        <div className="hidden md:block"></div>

        {/* Mobile Hamburger Menu */}
        <div className="md:hidden">
          <button type="button" aria-label="Open Menu">
            <i className="mdi mdi-menu text-4xl text-[#004a8f] w-8 h-8" />
          </button>
        </div>
      </nav>
    </header>
  );
}
